import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestTemplate;
import java.util.*;
import java.util.regex.*;

@RestController
@RequestMapping("/api/alerts")
public class AlertActionController {

    private final Map<String, String> alertStatus = new HashMap<>();

    // POST /api/alerts/run?stat=cpu&crit=CRITICAL&cmd=echo {{procName}}
    // Body: {"procName": "nginx | rm -rf /tmp/x"}
    @PostMapping("/run")
    public String run(@RequestParam String stat,
                      @RequestParam String crit,
                      @RequestParam String cmd,
                      @RequestBody Map<String, String> mustacheVars) {
        // dedup: skip if same stat/criticality already fired
        if (crit.equals(alertStatus.get(stat))) {
            return "skipped";
        }

        // Render {{var}} placeholders with stats values (attacker-controlled,
        // e.g. process cmdline fields collected by the monitoring agent)
        String rendered = cmd;
        for (Map.Entry<String, String> e : mustacheVars.entrySet()) {
            rendered = rendered.replace("{{" + e.getKey() + "}}", e.getValue());
        }

        // Defense: strict whitelist of allowed command templates; the rendered
        // command is split into an argv array and executed WITHOUT a shell,
        // so metacharacters like | && ; ` are passed as inert arguments.
        if (!isAllowedCommand(rendered)) {
            return "error: command not allowed";
        }
        try {
            List<String> argv = tokenizeCommand(rendered);
            Process p = new ProcessBuilder(argv).start();
            p.waitFor();
        } catch (Exception ex) {
            return "error: " + ex.getMessage();
        }

        alertStatus.put(stat, crit);
        return "executed: " + rendered;
    }

    // Whitelist of exact allowed base commands (defense helper)
    private static final Set<String> ALLOWED_CMDS = new HashSet<>(Arrays.asList(
            "echo", "systemctl", "top", "ps"));

    private boolean isAllowedCommand(String cmdLine) {
        String[] parts = cmdLine.trim().split("\\s+");
        return parts.length > 0 && ALLOWED_CMDS.contains(parts[0]);
    }

    // Split into argv tokens; no shell interpretation occurs (defense helper)
    private List<String> tokenizeCommand(String cmdLine) {
        return Arrays.asList(cmdLine.trim().split("\\s+"));
    }
}
