package main

import (
	"net/http"
	"net/url"
	"strings"

	"github.com/gin-gonic/gin"
)

// viewNameFromPath mimics DefaultRequestToViewNameTranslator:
// strips leading/trailing slashes and the file extension from the request URI.
func viewNameFromPath(path string) string {
	if strings.HasPrefix(path, "/") {
		path = path[1:]
	}
	if strings.HasSuffix(path, "/") {
		path = path[:len(path)-1]
	}
	if idx := strings.LastIndex(path, "."); idx > strings.LastIndex(path, "/") {
		path = path[:idx]
	}
	return path
}

// isAllowedRedirectTarget enforces a strict whitelist of trusted redirect hosts.
func isAllowedRedirectTarget(viewName string) (string, bool) {
	u, err := url.Parse("https://" + viewName)
	if err != nil || u.Host == "" {
		return "", false
	}
	switch u.Hostname() {
	case "www.example.com", "example.com":
		return u.String(), true
	default:
		return "", false
	}
}

func main() {
	r := gin.Default()

	// Wildcard route: view name is derived directly from the user-controlled URL.
	r.GET("/*viewPath", func(c *gin.Context) {
		raw := c.Param("viewPath")
		viewName := viewNameFromPath(raw)

		// If the derived "view name" is not a local template, fall back to
		// treating it as an external URL and redirect to it — but only if the
		// target host is on the whitelist.
		if !strings.HasSuffix(viewName, ".tmpl") {
			target, ok := isAllowedRedirectTarget(viewName)
			if !ok {
				c.String(http.StatusBadRequest, "redirect target not allowed")
				return
			}
			c.Redirect(http.StatusFound, target)
			return
		}
		c.HTML(http.StatusOK, viewName, nil)
	})

	r.Run(":8080")
}
