<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;

class PostRenderController extends Controller
{
    /**
     * Force-rerender a post: fill in missing image dimensions
     * by fetching image metadata from the URL stored on the card.
     */
    public function rerender(Request $request, int $postId)
    {
        $post = Post::findOrFail($postId);
        $mobiledoc = json_decode($post->mobiledoc, true);

        foreach ($mobiledoc['cards'] as &$card) {
            [$cardName, $payload] = $card;

            if ($cardName !== 'image' || empty($payload['src'])) {
                continue;
            }
            if (!empty($payload['width']) && !empty($payload['height'])) {
                continue;
            }

            try {
                // Defense: only allow https URLs whose host is in an exact allowlist
                $host = parse_url($payload['src'], PHP_URL_HOST);
                $allowedHosts = config('services.image_metadata.allowed_hosts', []);
                if ($host === false || $host === null || !in_array($host, $allowedHosts, true)) {
                    Log::warning('Blocked non-allowlisted image host for rerender');
                    continue;
                }
                if (strtolower(parse_url($payload['src'], PHP_URL_SCHEME) ?? '') !== 'https') {
                    continue;
                }
                // Defense: resolve DNS and reject private/loopback/link-local IPs before fetching
                $ip = gethostbyname($host);
                if (!filter_var($ip, FILTER_VALIDATE_IP)
                    || !filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) {
                    Log::warning('Blocked private/reserved IP for image rerender');
                    continue;
                }

                $response = Http::timeout(10)->get($payload['src']);
                $size = getimagesizefromstring($response->body());

                if ($size !== false) {
                    $payload['width'] = $size[0];
                    $payload['height'] = $size[1];
                }
            } catch (\Throwable $e) {
                Log::error($e->getMessage());
            }

            $card[1] = $payload;
        }

        $post->mobiledoc = json_encode($mobiledoc);
        $post->save();

        return response()->json(['ok' => true]);
    }
}
